/**
 * Host-side plugin: registers an RPC channel `/open-vscode` that spawns
 * `code` (VS Code CLI) at the workspace directory via the subprocess
 * capability.
 *
 * The browser half calls `ctx.connection.rpc.call('/open-vscode', 'launch', { cwd })`.
 * The host resolves the `code` executable, spawns it detached, and returns.
 */
import type { Context } from '@deepseek-ai/cordis'
// Type-only: pulls the subprocess Context merge (ctx.subprocess).
import type {} from '@deepseek-ai/dsh-subprocess'
// Type-only: pulls the connection Context merge (ctx.connection).
import type {} from '@deepseek-ai/dsh-client-connection'

/** Services required by this plugin: subprocess for spawning, connection for RPC. */
export const inject = ['subprocess', 'connection']

/**
 * Register the `/open-vscode` RPC handler.
 * @param ctx - Cordis host context.
 */
export function apply(ctx: Context): void {
  ctx.effect(() => {
    return ctx.connection.rpc.handle(
      '/open-vscode',
      async (endpoint, payload) => {
        if (endpoint !== 'launch') {
          return { ok: false, error: `unknown endpoint: ${endpoint}` }
        }
        const { cwd } = (payload ?? {}) as { cwd?: string }
        if (typeof cwd !== 'string' || cwd.length === 0) {
          return { ok: false, error: 'cwd is required' }
        }
        try {
          const exe = await ctx.subprocess.resolveExecutable('code')
          const handle = ctx.subprocess.spawn({
            argv: [exe, cwd],
            cwd,
            stdio: ['ignore', 'pipe', 'pipe'],
            graceMs: 5000,
          })
          // Fire-and-forget: VS Code launches detached, we don't wait for exit.
          handle.done.catch((err) => {
            console.error('[open-vscode] process failed:', err)
          })
          return { ok: true, data: { launched: true } }
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err)
          return { ok: false, error: `failed to launch VS Code: ${message}` }
        }
      },
      { authority: 'loopback' },
    )
  }, 'open-vscode: RPC handler')
}
